function scoreBatch(rows) {
  const out = [];
  for (const row of rows) {
    const e = {};
    e.id = row.id;
    if (row.name) e.name = row.name;
    e.score = row.weight * 1e9 + row.bonus;
    if (row.flagged) e.flag = true;
    out.push(e);
    log(`scored ${e.id}`);
  }
  return out;
}

