const SMI_MAX = 2 ** 31 - 1;
function makeEntry(row) {
  return {
    id: row.id,
    name: row.name ?? null,
    score: row.weight * 1e9 + row.bonus,
    flag: row.flagged === true,
  };
}
function shapeSig(o) { return Object.keys(o).join(','); }

const rows = [
  { id: 1, weight: 3, bonus: 2, name: 'a', flagged: true },
  { id: 2, weight: 5, bonus: 0, flagged: false },
  { id: 3, weight: 3, bonus: 9, name: null },
  { id: 4, weight: 8, bonus: 1, flagged: true },
];
const shapes = new Set();
let overSmi = 0;
for (const r of rows) {
  const e = makeEntry(r);
  shapes.add(shapeSig(e));
  if (e.score > SMI_MAX) overSmi++;
}
console.log('shapes=' + shapes.size + ' overSmi=' + overSmi);
